// Format message: turn one notify input {kind, title, body, url, attempts?, region?, shape?} into a Discord payload.
// Limits: content 2000 characters, embed description 4096, at most 10 embeds. Longer text is cut with '…'.
const LIMIT_CONTENT = 2000;
const LIMIT_DESCRIPTION = 4096;
const LIMIT_FIELD_VALUE = 1024;
const LIMIT_EMBEDS = 10;
const COLORS = { offer: 0x3498db, claim: 0x2ecc71, failure: 0xe74c3c };

// Cut text to max characters (code points). Adds '…' only when it had to cut.
function clip(text, max) {
  const chars = Array.from(String(text ?? ''));
  return chars.length <= max ? chars.join('') : chars.slice(0, max - 1).join('') + '…';
}

const item = $input.first().json;
if (!Object.hasOwn(COLORS, item.kind)) {
  throw new Error(`notify-discord: unknown kind '${item.kind}'`);
}
if (!item.title) {
  throw new Error('notify-discord: title is required');
}

// Claim results carry the attempt count, region and shape as optional fields.
const fields = [];
if (item.kind === 'claim') {
  if (item.attempts !== undefined) fields.push({ name: 'Attempts', value: String(item.attempts), inline: true });
  if (item.region) fields.push({ name: 'Region', value: clip(item.region, LIMIT_FIELD_VALUE), inline: true });
  if (item.shape) fields.push({ name: 'Shape', value: clip(item.shape, LIMIT_FIELD_VALUE), inline: true });
}

// The URL goes in the content so Discord shows it as a clickable link.
const content = clip([item.title, item.url].filter(Boolean).join('\n'), LIMIT_CONTENT);

const embed = { color: COLORS[item.kind] };
if (item.body) embed.description = clip(item.body, LIMIT_DESCRIPTION);
if (fields.length) embed.fields = fields;
const embeds = (embed.description || fields.length ? [embed] : []).slice(0, LIMIT_EMBEDS);

return [{ json: { username: 'VM Hunter', content, embeds } }];

// Check delivery: pass the response on when Discord answered 2xx (204 is success); otherwise fail the run so the error workflow reports it.
const response = $input.first().json;
if (response.statusCode < 200 || response.statusCode > 299) {
  throw new Error(`notify-discord: Discord returned HTTP ${response.statusCode}`);
}

return [{ json: response }];
